"""Billing for shipments. Rate lookups are billed, so the charge is remembered."""
import rates


class ShipmentBill:
    def __init__(self):
        self._shipments = []
        self._charge = None

    def add(self, shipment):
        """Add one shipment to the bill."""
        self._shipments.append(shipment)

    def charge(self):
        """Return the total charge: weight times the rate for each shipment's route.

        The result is remembered: asking again without adding anything makes no new rate lookups.
        """
        if self._charge is None:
            self._charge = sum(x.weight * rates.rate_for(x.route) for x in self._shipments)
        return self._charge


def describe_shipment(shipment):
    """Return a one-line description of a shipment."""
    return "%s: %s" % (shipment.route, shipment.weight)


def group_by_route(shipments):
    """Return a dict from route to the list of shipments with that route."""
    groups = {}
    for x in shipments:
        groups.setdefault(x.route, []).append(x)
    return groups

